import { defineConfig } from 'vitest/config';
import { resolve } from 'node:path';

export default defineConfig({
  resolve: {
    alias: [
      { find: '@shared', replacement: resolve(__dirname, '../src/shared') },
      { find: '@client', replacement: resolve(__dirname, '../src/client') },
      {
        find: /^react-native$/,
        replacement: resolve(__dirname, '__mocks__/react-native.js'),
      },
    ],
  },
  test: {
    environment: 'jsdom',
    globals: true,
    include: ['**/*.test.ts', '**/*.test.tsx'],
    exclude: ['**/node_modules/**', '**/.git/**'],
    clearMocks: true,
    restoreMocks: true,
    pool: 'forks',
  },
});

export const STARTUP_TIMEOUT_MS = 3_000;

export type BootstrapPhase = 'idle' | 'loading' | 'ready' | 'error';
export const BootstrapPhase = undefined as unknown as BootstrapPhase;

export type BootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | 'startup-timeout'
  | 'startup-tooling-error'
  | 'invalid-startup-config';
export const BootstrapErrorReason = undefined as unknown as BootstrapErrorReason;

export type BootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: BootstrapErrorReason;
      message: string;
      failedPhase: 'loading';
      recoverable: boolean;
    };
export const BootstrapState = undefined as unknown as BootstrapState;

export interface BootstrapResult {
  state: BootstrapState;
  transitions: BootstrapState[];
}

export interface BootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  timeoutMs?: number;
  now?: () => number;
  toolingCheck?: () => Promise<unknown>;
}

interface ValidUrlResult {
  ok: true;
  normalizedUrl: string;
}

interface InvalidUrlResult {
  ok: false;
  reason: Extract<BootstrapErrorReason, 'missing-api-base-url' | 'invalid-api-base-url'>;
  message: string;
}

const DEFAULT_IDLE_STATE: BootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_BOOTSTRAP_STATE = DEFAULT_IDLE_STATE;

export function createLoadingState(attempt: number, now: () => number): BootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
  };
}

export function validateApiBaseUrl(rawValue: string | undefined): ValidUrlResult | InvalidUrlResult {
  const value = rawValue?.trim();

  if (!value) {
    return {
      ok: false,
      reason: 'missing-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL is missing.',
    };
  }

  try {
    const parsed = new URL(value);

    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        ok: false,
        reason: 'invalid-api-base-url',
        message: 'EXPO_PUBLIC_API_BASE_URL must use http or https.',
      };
    }

    parsed.hash = '';

    return {
      ok: true,
      normalizedUrl: parsed.toString().replace(/\/$/, ''),
    };
  } catch {
    return {
      ok: false,
      reason: 'invalid-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL must be a valid absolute URL.',
    };
  }
}

function toBootstrapError(
  reason: BootstrapErrorReason,
  message: string,
  attempt: number,
  recoverable = true,
): BootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'loading',
    recoverable,
  };
}

function isValidStartupToolingResult(result: unknown): result is { status: 'ok' } {
  return !!result && typeof result === 'object' && (result as { status?: string }).status === 'ok';
}

async function defaultToolingCheck(): Promise<{ status: 'ok' }> {
  return { status: 'ok' };
}

async function runWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }
}

export async function runAppBootstrap(options: BootstrapOptions = {}): Promise<BootstrapResult> {
  const now = options.now ?? Date.now;
  const attempt = Math.max(1, options.attempt ?? 1);
  const timeoutMs = options.timeoutMs ?? STARTUP_TIMEOUT_MS;
  const toolingCheck = options.toolingCheck ?? defaultToolingCheck;
  const env = options.env ?? process.env;

  const loadingState = createLoadingState(attempt, now);
  const transitions: BootstrapState[] = [loadingState];

  try {
    const toolingResult = await runWithTimeout(
      toolingCheck(),
      timeoutMs,
      'Startup tooling check timed out.',
    );

    if (!isValidStartupToolingResult(toolingResult)) {
      const malformedConfigState = toBootstrapError(
        'invalid-startup-config',
        'Startup tooling returned an invalid configuration shape.',
        attempt,
        false,
      );
      transitions.push(malformedConfigState);
      return {
        state: malformedConfigState,
        transitions,
      };
    }
  } catch (error) {
    const reason: BootstrapErrorReason =
      error instanceof Error && error.message === 'Startup tooling check timed out.'
        ? 'startup-timeout'
        : 'startup-tooling-error';

    const toolingErrorState = toBootstrapError(
      reason,
      error instanceof Error ? error.message : 'Startup tooling check failed.',
      attempt,
      true,
    );
    transitions.push(toolingErrorState);

    return {
      state: toolingErrorState,
      transitions,
    };
  }

  const apiValidation = validateApiBaseUrl(
    env.EXPO_PUBLIC_API_BASE_URL && env.EXPO_PUBLIC_API_BASE_URL !== 'undefined'
      ? env.EXPO_PUBLIC_API_BASE_URL
      : 'http://10.0.2.2:3001',
  );

  if (!apiValidation.ok) {
    const configErrorState = toBootstrapError(
      apiValidation.reason,
      apiValidation.message,
      attempt,
      false,
    );
    transitions.push(configErrorState);

    return {
      state: configErrorState,
      transitions,
    };
  }

  const readyState: BootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiValidation.normalizedUrl,
  };
  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

/**
 * Theme system for CampusNav.
 * Exports color palettes, spacing scale, typography, and the useTheme hook.
 */

import { useColorScheme } from 'react-native';

import { darkColors, lightColors } from './colors';
import { spacing } from './spacing';
import { typography } from './typography';

export { darkColors, lightColors } from './colors';
export { spacing } from './spacing';
export { typography } from './typography';

export interface Theme {
  colors: typeof darkColors | typeof lightColors;
  spacing: typeof spacing;
  typography: typeof typography;
  isDark: boolean;
}

/**
 * Returns the current theme based on the system color scheme.
 *
 * Usage:
 *   const { colors, spacing, typography, isDark } = useTheme();
 */
export function useTheme(): Theme {
  const colorScheme = useColorScheme();
  const isDark = colorScheme === 'dark';
  return {
    colors: isDark ? darkColors : lightColors,
    spacing,
    typography,
    isDark,
  };
}

import { describe, it, expect, vi } from 'vitest';
import {
  STARTUP_TIMEOUT_MS,
  validateApiBaseUrl,
  runAppBootstrap,
} from './appBootstrap';

describe('runAppBootstrap', () => {
  it('transitions from loading to ready when EXPO_PUBLIC_API_BASE_URL is valid', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com/',
      },
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'ready']);
    expect(result.state.phase).toBe('ready');

    if (result.state.phase !== 'ready') {
      throw new Error('Expected ready bootstrap state.');
    }

    expect(result.state.apiBaseUrl).toBe('https://campusnav.example.com');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error when EXPO_PUBLIC_API_BASE_URL is missing', async () => {
    const result = await runAppBootstrap({
      env: {},
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.transitions.map((state) => state.phase)).toEqual(['loading', 'error']);
    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('missing-api-base-url');
    expect(result.state.failedPhase).toBe('loading');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error when EXPO_PUBLIC_API_BASE_URL is malformed', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'not-a-url',
      },
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('invalid-api-base-url');
    expect(result.state.authRequired).toBe(false);
  });

  it('transitions to error on startup timeout with bounded wait', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
      },
      timeoutMs: 15,
      toolingCheck: () => new Promise((resolve) => setTimeout(() => resolve({ status: 'ok' }), 30)),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('startup-timeout');
    expect(result.state.message).toContain('timed out');
  });

  it('transitions to error when startup tooling returns malformed config shape', async () => {
    const result = await runAppBootstrap({
      env: {
        EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
      },
      toolingCheck: async () => ({ ok: true }),
    });

    expect(result.state.phase).toBe('error');

    if (result.state.phase !== 'error') {
      throw new Error('Expected error bootstrap state.');
    }

    expect(result.state.reason).toBe('invalid-startup-config');
  });

  it('is idempotent across repeated invocation and never regresses to auth-required state', async () => {
    const env = {
      EXPO_PUBLIC_API_BASE_URL: 'https://campusnav.example.com',
    };

    const first = await runAppBootstrap({
      env,
      attempt: 1,
      toolingCheck: async () => ({ status: 'ok' }),
    });

    const second = await runAppBootstrap({
      env,
      attempt: 2,
      toolingCheck: async () => ({ status: 'ok' }),
    });

    expect(first.state.phase).toBe('ready');
    expect(second.state.phase).toBe('ready');

    if (first.state.phase !== 'ready' || second.state.phase !== 'ready') {
      throw new Error('Expected repeated bootstrap calls to be ready.');
    }

    expect(first.state.apiBaseUrl).toBe(second.state.apiBaseUrl);
    expect(first.state.authRequired).toBe(false);
    expect(second.state.authRequired).toBe(false);
    expect(second.state.attempt).toBeGreaterThan(first.state.attempt);
  });
});

describe('validateApiBaseUrl', () => {
  it('requires a URL with http/https protocol', () => {
    const ftpResult = validateApiBaseUrl('ftp://example.com/path');
    expect(ftpResult.ok).toBe(false);

    if (ftpResult.ok) {
      throw new Error('Expected invalid result for unsupported protocol.');
    }

    expect(ftpResult.reason).toBe('invalid-api-base-url');
  });

  it('keeps startup timeout constant explicit and bounded', () => {
    expect(STARTUP_TIMEOUT_MS).toBeGreaterThan(0);
    expect(STARTUP_TIMEOUT_MS).toBeLessThanOrEqual(5_000);
  });
});

/**
 * Tests for useLocationSearch hook.
 */

import { renderHook } from '@testing-library/react-native';
import { useLocationSearch } from './useLocationSearch';
import { normalizeNavGraph } from '../domain/navGraph';
import { NavBuilding, NavFloor, NavGraph } from '../../src/shared/types';

function createTestNavGraph(): NavGraph {
  const libF1Nodes = [
    { id: 'lib-f1-entrance', x: 0.5, y: 0.9, floorId: 1, type: 'entrance' as const, searchable: true, label: 'Main Entrance', description: 'Library main entrance' },
    { id: 'lib-f1-reception', x: 0.5, y: 0.8, floorId: 1, type: 'room' as const, searchable: true, label: 'Reception', roomNumber: '101', description: 'Front desk' },
    { id: 'lib-f1-study-a', x: 0.3, y: 0.6, floorId: 1, type: 'room' as const, searchable: true, label: 'Study Room A', roomNumber: '102' },
    { id: 'lib-f1-stairs', x: 0.9, y: 0.5, floorId: 1, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeAboveId: 'lib-f2-stairs', connectsToFloorAboveId: 2 },
    { id: 'lib-f1-elevator', x: 0.1, y: 0.5, floorId: 1, type: 'elevator' as const, searchable: true, label: 'Elevator' },
  ];
  const libF2Nodes = [
    { id: 'lib-f2-stairs', x: 0.9, y: 0.5, floorId: 2, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeBelowId: 'lib-f1-stairs', connectsToFloorBelowId: 1 },
    { id: 'lib-f2-cafeteria', x: 0.5, y: 0.7, floorId: 2, type: 'landmark' as const, searchable: true, label: 'Cafeteria', roomNumber: '201' },
  ];
  const sciF1Nodes = [
    { id: 'sci-f1-entrance', x: 0.5, y: 0.9, floorId: 3, type: 'entrance' as const, searchable: true, label: 'Science Entrance', description: 'Science building main entrance' },
    { id: 'sci-f1-lab-101', x: 0.3, y: 0.5, floorId: 3, type: 'room' as const, searchable: true, label: 'Chemistry Lab', roomNumber: '101', description: 'Teaching chemistry lab' },
    { id: 'sci-f1-restroom', x: 0.1, y: 0.3, floorId: 3, type: 'restroom' as const, searchable: true, label: 'Restroom' },
    { id: 'sci-f1-stairs', x: 0.9, y: 0.5, floorId: 3, type: 'stairs' as const, searchable: false, label: 'Stairs' },
  ];
  return {
    buildings: [
      { id: 1, name: 'Library', floors: [
        { id: 1, floorNumber: 1, imagePath: '/lib-f1.png', updatedAt: '2024-01-01T00:00:00Z', nodes: libF1Nodes, edges: [{ id: 'e1', sourceId: 'lib-f1-entrance', targetId: 'lib-f1-reception', standardWeight: 0.1, accessibleWeight: 0.1, accessible: true, bidirectional: true }] },
        { id: 2, floorNumber: 2, imagePath: '/lib-f2.png', updatedAt: '2024-01-01T00:00:00Z', nodes: libF2Nodes, edges: [{ id: 'e2', sourceId: 'lib-f2-stairs', targetId: 'lib-f2-cafeteria', standardWeight: 0.3, accessibleWeight: 0.3, accessible: true, bidirectional: true }] },
      ]},
      { id: 2, name: 'Science Building', floors: [
        { id: 3, floorNumber: 1, imagePath: '/sci-f1.png', updatedAt: '2024-01-01T00:00:00Z', nodes: sciF1Nodes, edges: [{ id: 'e3', sourceId: 'sci-f1-entrance', targetId: 'sci-f1-lab-101', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true }] },
      ]},
    ],
  };
}

function makeGraph() {
  const result = normalizeNavGraph(createTestNavGraph());
  if (!result.ok) throw new Error('Failed to normalize: ' + result.error.message);
  return result.data;
}

describe('useLocationSearch', () => {
  describe('empty query', () => {
    it('returns all searchable nodes grouped by building/floor', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      expect(result.current.buildings).toHaveLength(2);
      expect(result.current.buildings[0]?.buildingName).toBe('Library');
    });

    it('excludes non-searchable nodes (stairs)', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const allNodeIds = result.current.buildings.flatMap(b => b.floors.flatMap(f => f.nodes.map(n => n.node.id)));
      expect(allNodeIds).not.toContain('lib-f1-stairs');
      expect(allNodeIds).not.toContain('sci-f1-stairs');
    });

    it('totalMatches counts searchable nodes only', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      // Library F1: entrance, reception, study-a, elevator = 4; F2: cafeteria = 1; Science F1: entrance, lab-101, restroom = 3
      expect(result.current.totalMatches).toBe(8);
    });

    it('buildings sorted alphabetically', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      expect(result.current.buildings.map(b => b.buildingName)).toEqual(['Library', 'Science Building']);
    });

    it('floors sorted by floor number', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const libFloors = result.current.buildings.find(b => b.buildingName === 'Library')?.floors.map(f => f.floorNumber);
      expect(libFloors).toEqual([1, 2]);
    });

    it('nodes sorted by label', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));
      const libF1Labels = result.current.buildings.find(b => b.buildingName === 'Library')?.floors.find(f => f.floorNumber === 1)?.nodes.map(n => n.node.label);
      expect(libF1Labels).toEqual(['Elevator', 'Main Entrance', 'Reception', 'Study Room A']);
    });
  });

  describe('prefix matching', () => {
    it('matches label prefix "Study"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Study'));
      expect(result.current.totalMatches).toBe(1);
    });

    it('case-insensitive matching', () => {
      const graph = makeGraph();
      const { result: lower } = renderHook(() => useLocationSearch(graph, 'study'));
      const { result: upper } = renderHook(() => useLocationSearch(graph, 'STUDY'));
      expect(lower.current.totalMatches).toBe(upper.current.totalMatches);
    });

    it('matches room number prefix "10"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '10'));
      expect(result.current.totalMatches).toBe(2); // 101 Reception + 101 Chemistry Lab
    });

    it('matches description "chemistry"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'chemistry'));
      expect(result.current.totalMatches).toBe(1);
    });

    it('matches building name prefix "Sci"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Sci'));
      expect(result.current.buildings).toHaveLength(1);
      expect(result.current.buildings[0]?.buildingName).toBe('Science Building');
    });

    it('matches building name prefix "Lib"', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Lib'));
      expect(result.current.buildings).toHaveLength(1);
      expect(result.current.buildings[0]?.buildingName).toBe('Library');
    });
  });

  describe('type filter', () => {
    it('excludes non-room nodes when typeFilter is {room}', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '', new Set(['room'])));
      const allTypes = result.current.buildings.flatMap(b => b.floors.flatMap(f => f.nodes.map(n => n.node.type)));
      expect(allTypes.every(t => t === 'room')).toBe(true);
      expect(allTypes).toHaveLength(3);
    });

    it('filters to restroom only', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, '', new Set(['restroom'])));
      expect(result.current.totalMatches).toBe(1);
    });
  });

  describe('nonsense query', () => {
    it('returns empty result', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'xyz123'));
      expect(result.current.buildings).toHaveLength(0);
      expect(result.current.totalMatches).toBe(0);
    });
  });

  describe('result structure', () => {
    it('SearchNode includes full NavNode plus context', () => {
      const graph = makeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Reception'));
      const sn = result.current.buildings[0].floors[0].nodes[0];
      expect(sn.node.id).toBe('lib-f1-reception');
      expect(sn.buildingId).toBe(1);
      expect(sn.buildingName).toBe('Library');
      expect(sn.floorId).toBe(1);
      expect(sn.floorNumber).toBe(1);
    });
  });
});

/**
 * Tests for mobile/hooks/useRouteSelection.ts
 *
 * Covers:
 * - setFromTap advances activeField
 * - swap exchanges start/destination
 * - clearAll resets state
 * - tapping same field skips duplicate (swap behavior)
 */

import { describe, expect, it } from 'vitest';
import { renderHook, act } from '@testing-library/react-native';
import { useRouteSelection } from './useRouteSelection';
import { NavNode } from '../../src/shared/types';

function makeNode(id: string, label = `Node ${id}`): NavNode {
  return {
    id,
    x: 0.5,
    y: 0.5,
    floorId: 1,
    type: 'room',
    searchable: true,
    label,
    roomNumber: id,
  };
}

describe('useRouteSelection', () => {
  describe('initial state', () => {
    it('starts with null start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('starts with activeField = "start"', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.activeField).toBe('start');
    });

    it('starts with bothSelected = false', () => {
      const { result } = renderHook(() => useRouteSelection());
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('setStart', () => {
    it('sets start node and advances activeField to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());
      const node = makeNode('node-a');

      act(() => {
        result.current.setStart(node);
      });

      expect(result.current.start).toEqual(node);
      expect(result.current.activeField).toBe('destination');
    });
  });

  describe('setDestination', () => {
    it('sets destination node and advances activeField to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('dest-a'));
      });

      expect(result.current.destination).toBeDefined();
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('setFromTap', () => {
    it('when activeField is "start", assigns to start and advances to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());
      const node = makeNode('tap-a');

      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.start).toEqual(node);
      expect(result.current.activeField).toBe('destination');
    });

    it('when activeField is "destination", assigns to destination and advances to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Advance to destination field
      act(() => {
        result.current.setActiveField('destination');
      });

      const node = makeNode('tap-b');
      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.destination).toEqual(node);
      expect(result.current.activeField).toBe('start');
    });

    it('tapping the other field swaps start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Set start first
      act(() => {
        result.current.setStart(makeNode('start-x'));
      });

      // Now tap what is currently the start (node-x) while activeField is "destination"
      // This should trigger the swap
      act(() => {
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.setFromTap(makeNode('start-x'));
      });

      // The tapped node becomes destination, start-x becomes start
      // After swap: start = tapped node (start-x), dest = previous start (start-x)
      // Actually: when activeField=dest and start.id === tapped.id, swap happens
      // So: setStartState(prevDest=null) → start=start-x (same), setDestinationState(prevStart=start-x) → dest=start-x
      // Result: start=start-x, dest=start-x, activeField='start'
      expect(result.current.start?.id).toBe('start-x');
      expect(result.current.destination?.id).toBe('start-x');
    });

    it('tapping the same field that is already set skips duplicate and advances', () => {
      const { result } = renderHook(() => useRouteSelection());

      // Set start
      act(() => {
        result.current.setStart(makeNode('start-y'));
      });

      // activeField is now "destination"
      // Now tap what is currently the destination (null) — no swap, just set
      const node = makeNode('new-dest');
      act(() => {
        result.current.setFromTap(node);
      });

      expect(result.current.start?.id).toBe('start-y');
      expect(result.current.destination?.id).toBe('new-dest');
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('swap', () => {
    it('exchanges start and destination', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('old-start'));
        result.current.setDestination(makeNode('old-dest'));
      });

      act(() => {
        result.current.swap();
      });

      expect(result.current.start?.id).toBe('old-dest');
      expect(result.current.destination?.id).toBe('old-start');
    });

    it('is a no-op when both are null', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.swap();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
    });

    it('is a no-op when only one is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('only-start'));
      });

      act(() => {
        result.current.swap();
      });

      // With one null, the swap still exchanges null with the set value
      expect(result.current.start?.id ?? null).toBeNull();
      expect(result.current.destination?.id).toBe('only-start');
    });
  });

  describe('clearAll', () => {
    it('resets start, destination, and activeField', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setDestination(makeNode('d'));
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.clearAll();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('start');
      expect(result.current.bothSelected).toBe(false);
    });
  });

  describe('clearStart', () => {
    it('clears start and resets activeField to "start"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setActiveField('destination');
      });

      act(() => {
        result.current.clearStart();
      });

      expect(result.current.start).toBeNull();
      expect(result.current.activeField).toBe('start');
    });
  });

  describe('clearDestination', () => {
    it('clears destination and resets activeField to "destination"', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('d'));
      });

      act(() => {
        result.current.clearDestination();
      });

      expect(result.current.destination).toBeNull();
      expect(result.current.activeField).toBe('destination');
    });
  });

  describe('bothSelected', () => {
    it('is true when both start and destination are set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
        result.current.setDestination(makeNode('d'));
      });

      expect(result.current.bothSelected).toBe(true);
    });

    it('is false when only start is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setStart(makeNode('s'));
      });

      expect(result.current.bothSelected).toBe(false);
    });

    it('is false when only destination is set', () => {
      const { result } = renderHook(() => useRouteSelection());

      act(() => {
        result.current.setDestination(makeNode('d'));
      });

      expect(result.current.bothSelected).toBe(false);
    });
  });
});

/**
 * In-memory location search over a NormalizedNavGraph.
 * Case-insensitive prefix match on label, roomNumber, description, buildingName.
 * Results grouped by building → floor, sorted alphabetically/numerically.
 */

import { useMemo } from 'react';
import { NormalizedNavGraph } from '../domain/navGraph';
import { NavNodeType } from '../../src/shared/types';

export interface SearchNode {
  node: import('../../src/shared/types').NavNode;
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
}
export interface SearchFloor { floorId: number; floorNumber: number; nodes: SearchNode[]; }
export interface SearchBuilding { buildingId: number; buildingName: string; floors: SearchFloor[]; }
export interface UseLocationSearchResult { buildings: SearchBuilding[]; totalMatches: number; }

function isPrefixMatch(query: string, target: string): boolean {
  return query.length === 0 || target.toLowerCase().startsWith(query.toLowerCase());
}

export function useLocationSearch(
  graph: NormalizedNavGraph,
  query: string,
  typeFilter?: Set<NavNodeType>,
): UseLocationSearchResult {
  return useMemo(() => {
    const trimmed = query.trim();
    const buildings: SearchBuilding[] = [];
    let totalMatches = 0;

    for (const building of graph.graph.buildings) {
      const matchedFloors: SearchFloor[] = [];

      for (const floor of building.floors) {
        const floorRec = graph.floorById.get(floor.id);
        const floorNumber = floorRec?.floor.floorNumber ?? floor.floorNumber;
        const matchedNodes: SearchNode[] = [];

        for (const node of floor.nodes) {
          if (!node.searchable) continue;
          if (typeFilter && !typeFilter.has(node.type)) continue;
          if (trimmed.length > 0) {
            const labelOk = isPrefixMatch(trimmed, node.label);
            const roomOk = node.roomNumber && isPrefixMatch(trimmed, node.roomNumber);
            const descOk = node.description && isPrefixMatch(trimmed, node.description);
            const bldOk = isPrefixMatch(trimmed, building.name);
            if (!labelOk && !roomOk && !descOk && !bldOk) continue;
          }
          matchedNodes.push({ node, buildingId: building.id, buildingName: building.name, floorId: floor.id, floorNumber });
        }

        if (matchedNodes.length > 0) {
          matchedNodes.sort((a, b) => a.node.label.localeCompare(b.node.label));
          matchedFloors.push({ floorId: floor.id, floorNumber, nodes: matchedNodes });
          totalMatches += matchedNodes.length;
        }
      }

      if (matchedFloors.length > 0) {
        matchedFloors.sort((a, b) => a.floorNumber - b.floorNumber);
        buildings.push({ buildingId: building.id, buildingName: building.name, floors: matchedFloors });
      }
    }

    buildings.sort((a, b) => a.buildingName.localeCompare(b.buildingName));
    return { buildings, totalMatches };
  }, [graph, query, typeFilter]);
}

/**
 * Mobile port of src/client/hooks/useRouteSelection.ts.
 *
 * Changes from web version:
 * - RouteSelection interface inlined (no shared module dependency)
 */

import { useCallback, useMemo, useState } from 'react';

// NavNode placeholder - shared types import temporarily disabled for debug
type NavNode = { id: string; name: string; floorId: number; x: number; y: number; category?: string };

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly activeField: 'start' | 'destination';
  readonly bothSelected: boolean;
  readonly setStart: (node: NavNode | null) => void;
  readonly setDestination: (node: NavNode | null) => void;
  readonly setActiveField: (field: 'start' | 'destination') => void;
  /** Assigns a tapped node to the active field, auto-advancing to the other field. */
  readonly setFromTap: (node: NavNode) => void;
  /** Exchanges start and destination. No-op when both are null. */
  readonly swap: () => void;
  readonly clearStart: () => void;
  readonly clearDestination: () => void;
  readonly clearAll: () => void;
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null);
  const [destination, setDestinationState] = useState<NavNode | null>(null);
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start');

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node);
    setActiveField('destination');
  }, []);

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node);
    setActiveField('start');
  }, []);

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap start ↔ destination
        if (destination?.id === node.id) {
          setDestinationState(start);
          setStartState(node);
          setActiveField('destination');
        } else {
          setStartState(node);
          setActiveField('destination');
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap start ↔ destination
        if (start?.id === node.id) {
          setStartState(destination);
          setDestinationState(node);
          setActiveField('start');
        } else {
          setDestinationState(node);
          setActiveField('start');
        }
      }
    },
    [activeField, start, destination],
  );

  const swap = useCallback(() => {
    if (start === null && destination === null) return;
    const prevStart = start;
    const prevDest = destination;
    setStartState(prevDest);
    setDestinationState(prevStart);
  }, [start, destination]);

  const clearStart = useCallback(() => {
    setStartState(null);
    setActiveField('start');
  }, []);

  const clearDestination = useCallback(() => {
    setDestinationState(null);
    setActiveField('destination');
  }, []);

  const clearAll = useCallback(() => {
    setStartState(null);
    setDestinationState(null);
    setActiveField('start');
  }, []);

  const bothSelected = useMemo(
    () => start !== null && destination !== null,
    [start, destination],
  );

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  };
}

/**
 * MapViewportFloor — floor-switching extension of MapViewport.
 *
 * Composes:
 * - MapViewport (floor plan image with pan/pinch/rotate controls)
 * - Floor selector strip (horizontal ScrollView of floor buttons)
 * - RoutePathOverlay (polyline overlay on active floor)
 *
 * The active floor target is tracked in state and drives both
 * which image is shown and which floor segment is rendered.
 */

import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { MapViewport } from './MapViewport';
import { RoutePathOverlay, RoutePathPoint } from '../components/route/RoutePathOverlay';
import { FloorPlanTarget } from '../data/mapApiClient';
import { MapTransform } from './mapTransform';
import { ViewportDimensions } from './mapTransform';

/* ─── Props ─── */

export interface MapViewportFloorProps {
  /** MapViewport props */
  onTransformChange?: (transform: MapTransform) => void;
  /** All available floor targets for the active route */
  floorTargets: FloorPlanTarget[];
  /** Currently selected floor target */
  activeFloorTarget: FloorPlanTarget | null;
  /** Floor ID for the active target (used for route path overlay filtering) */
  activeFloorId: number;
  /** Route path waypoints (normalized coordinates) */
  routePath: RoutePathPoint[];
  /** Called when user presses a floor button */
  onFloorChange: (target: FloorPlanTarget) => void;
  /** Whether to show the route path overlay */
  showRouteOverlay?: boolean;
  /** Whether to show the floor selector strip */
  showFloorSelector?: boolean;
  /** Device heading in degrees (0–360), applied to map rotation during active guidance. */
  headingDegrees?: number | null;
}

/* ─── State ─── */

interface FloorButtonData {
  target: FloorPlanTarget;
  label: string;
  isActive: boolean;
}

/* ─── Component ─── */

export function MapViewportFloor({
  onTransformChange,
  floorTargets,
  activeFloorTarget,
  activeFloorId,
  routePath,
  onFloorChange,
  showRouteOverlay = true,
  showFloorSelector = true,
  headingDegrees,
}: MapViewportFloorProps) {
  const [transform, setTransform] = useState<MapTransform>(() => ({
    scale: 1,
    rotationDeg: 0,
    translation: { x: 0, y: 0 },
    headingRotationDeg: 0,
  }));
  const [viewportDimensions, setViewportDimensions] = useState<ViewportDimensions>({ width: 300, height: 300 });

  const handleTransformChange = useCallback(
    (t: MapTransform) => {
      setTransform(t);
      onTransformChange?.(t);
    },
    [onTransformChange],
  );

  // Build floor button data
  const floorButtons: FloorButtonData[] = floorTargets.map(target => ({
    target,
    label: `Bldg ${target.buildingId} Fl ${target.floorNumber}`,
    isActive: activeFloorTarget !== null
      && activeFloorTarget.buildingId === target.buildingId
      && activeFloorTarget.floorNumber === target.floorNumber,
  }));

  return (
    <View style={styles.container}>
      {/* Map viewport with optional route overlay */}
      <View style={styles.mapContainer}>
        <MapViewport
          imageUri=""
          onTransformChange={handleTransformChange}
          headingRotationDeg={headingDegrees ?? undefined}
        />
        {showRouteOverlay && activeFloorTarget && (
          <RoutePathOverlay
            path={routePath}
            activeFloorId={activeFloorId}
            viewport={viewportDimensions}
            scale={transform.scale}
          />
        )}
      </View>

      {/* Floor selector strip */}
      {showFloorSelector && floorButtons.length > 0 && (
        <View style={styles.floorSelector}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.floorScrollContent}
          >
            {floorButtons.map((btn, idx) => (
              <Pressable
                key={`floor-${idx}`}
                style={[styles.floorButton, btn.isActive && styles.floorButtonActive]}
                onPress={() => onFloorChange(btn.target)}
              >
                <Text style={[styles.floorButtonText, btn.isActive && styles.floorButtonTextActive]}>
                  {btn.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}

