}

function makeSelection() {
  return {
    start: null as ReturnType<typeof vi.fn>,
    destination: null,
    activeField: 'start' as const,
    bothSelected: false,
    setStart: vi.fn(),
    setDestination: vi.fn(),
    setActiveField: vi.fn(),
    setFromTap: vi.fn(),
    swap: vi.fn(),
    clearStart: vi.fn(),
    clearDestination: vi.fn(),
    clearAll: vi.fn(),
  };
}

// Minimal route selection mock that works with the component
import { NavNode } from '../../../src/shared/types';

function createMockSelection(overrides?: Partial<{
  start: NavNode | null;
  destination: NavNode | null;
  activeField: 'start' | 'destination';
  onSetStart: () => void;
  onSetDestination: () => void;
  onSwap: () => void;
  onSetActiveField: (f: 'start' | 'destination') => void;
}>) {
  const mockStart = vi.fn();
  const mockDest = vi.fn();
  const mockSwap = vi.fn();
  const mockSetAF = vi.fn();
  return {
    start: overrides?.start ?? null,
    destination: overrides?.destination ?? null,
    activeField: overrides?.activeField ?? 'start',
    bothSelected: (overrides?.start !== null && overrides?.destination !== null) ?? false,
    setStart: mockStart,
    setDestination: mockDest,
    setActiveField: mockSetAF,
    setFromTap: vi.fn(),
    swap: mockSwap,
    clearStart: vi.fn(),
    clearDestination: vi.fn(),
    clearAll: vi.fn(),
    _mockFns: { mockStart, mockDest, mockSwap, mockSetAF },
    ...overrides,
  };
}

describe('DestinationPicker', () => {
  it('renders search input', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);
    expect(screen.getByPlaceholderText('Search location...')).toBeTruthy();
  });

  it('renders building items when graph is loaded', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);
    expect(screen.getByText('Library')).toBeTruthy();
    expect(screen.getByText('Science Building')).toBeTruthy();
  });

  it('shows floor and node counts in building metadata', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);
    // Library: 2 floors, 4 searchable nodes (stairs excluded)
    expect(screen.getByText(/2 floors/)).toBeTruthy();
    expect(screen.getByText(/4 locations/)).toBeTruthy();
  });

  it('expanding building shows floor headers and nodes', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    // Tap building header to expand
    fireEvent.press(screen.getByText('Library'));

    expect(screen.getByText('Floor 1')).toBeTruthy();
    expect(screen.getByText('Floor 2')).toBeTruthy();
  });

  it('expanded building shows searchable nodes', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    fireEvent.press(screen.getByText('Library'));

    // Stairs is not searchable, so should not appear
    expect(screen.getByText('Reception')).toBeTruthy();
    expect(screen.getByText('Study Room')).toBeTruthy();
    expect(screen.getByText('Elevator')).toBeTruthy();
    expect(screen.queryByText('Stairs')).toBeNull();
  });

  it('search filters node results', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    // Expand Library
    fireEvent.press(screen.getByText('Library'));

    // Type in search box
    const input = screen.getByPlaceholderText('Search location...');
    fireEvent.changeText(input, 'Study');

    // Should only show Study Room
    expect(screen.getByText('Study Room')).toBeTruthy();
    expect(screen.queryByText('Reception')).toBeNull();
  });

  it('search by room number works', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    fireEvent.press(screen.getByText('Library'));

    const input = screen.getByPlaceholderText('Search location...');
    fireEvent.changeText(input, '101');

    expect(screen.getByText('Reception')).toBeTruthy();
  });

  it('calling onNodeSelect with correct node on press', () => {
    const graph = makeGraph();
    const onNodeSelect = vi.fn();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={onNodeSelect} />);

    fireEvent.press(screen.getByText('Library'));
    fireEvent.press(screen.getByText('Reception'));

    expect(onNodeSelect).toHaveBeenCalledTimes(1);
    expect(onNodeSelect.mock.calls[0][0].id).toBe('n1');
  });

  it('shows accessible icon for elevator nodes', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    fireEvent.press(screen.getByText('Library'));

    expect(screen.getByText('♿')).toBeTruthy();
  });

  it('active field chip is highlighted', () => {
    const graph = makeGraph();
    const selection = createMockSelection({ activeField: 'destination' });
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    // Both chips should be visible, destination active
    expect(screen.getByText(/^Dest/)).toBeTruthy();
    expect(screen.getByText(/^Start/)).toBeTruthy();
  });

  it('swap button appears when start or destination is set', () => {
    const graph = makeGraph();
    const selection = createMockSelection({ start: graph.nodeById.get('n1')?.node ?? null });
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    expect(screen.getByText('⇄ Swap')).toBeTruthy();
  });

  it('result count updates after search', () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    // Initial: all searchable nodes = 4 (Library) + 1 (Science) = 5
    expect(screen.getByText(/^5 results$/)).toBeTruthy();

    const input = screen.getByPlaceholderText('Search location...');
    fireEvent.changeText(input, 'Caf');

    // After debounce: only Cafeteria = 1
    // Wait for debounce (300ms)
    return new Promise(resolve => setTimeout(resolve, 350));
  });

  it('empty result message shown for nonsense query', async () => {
    const graph = makeGraph();
    const selection = createMockSelection();
    render(<DestinationPicker graph={graph} selection={selection} onNodeSelect={vi.fn()} />);

    const input = screen.getByPlaceholderText('Search location...');
    fireEvent.changeText(input, 'xyz123nonsense');

    // Wait for debounce
    await new Promise(resolve => setTimeout(resolve, 350));

    expect(screen.getByText('No locations match your search.')).toBeTruthy();
  });
});

/**
 * Tests for ConfidenceIndicator component.
 * Written as .test.tsx but uses React.createElement to avoid Vite 7's
 * TSX transform issue (oxc can't parse TypeScript `import type` syntax).
 * @testing-library/react-native is used via @testing-library/react-native/build.
 */

import { describe, expect, it, vi } from 'vitest';
import * as React from 'react';
import { render, screen, fireEvent } from '@testing-library/react-native';
import { ConfidenceIndicator } from './ConfidenceIndicator';

const h = React.createElement;

describe('ConfidenceIndicator', () => {
  it('renders with testID', () => {
    render(h(ConfidenceIndicator, { confidence: 'high' }));
    expect(screen.getByTestId('confidence-indicator')).toBeTruthy();
  });

  it('has Pressable accessibility role', () => {
    render(h(ConfidenceIndicator, { confidence: 'medium' }));
    const el = screen.getByTestId('confidence-indicator');
    expect(el.props.accessibilityRole).toBe('button');
  });

  it('shows accessibility label with confidence level', () => {
    render(h(ConfidenceIndicator, { confidence: 'low' }));
    const el = screen.getByTestId('confidence-indicator');
    expect(el.props.accessibilityLabel).toBe('GPS confidence: low');
  });

  it('tapping toggles the detail label (tap to show)', () => {
    render(h(ConfidenceIndicator, { confidence: 'high' }));
    // Initially no label
    expect(screen.queryByText('GPS OK')).toBeNull();
    // Tap
    fireEvent.press(screen.getByTestId('confidence-indicator'));
    expect(screen.getByText('GPS OK')).toBeTruthy();
  });

  it('tapping again hides the detail label', () => {
    render(h(ConfidenceIndicator, { confidence: 'low' }));
    const el = screen.getByTestId('confidence-indicator');
    // Show
    fireEvent.press(el);
    expect(screen.getByText('Weak GPS')).toBeTruthy();
    // Hide
    fireEvent.press(el);
    expect(screen.queryByText('Weak GPS')).toBeNull();
  });

  it('renders correctly for none confidence', () => {
    render(h(ConfidenceIndicator, { confidence: 'none' }));
    const el = screen.getByTestId('confidence-indicator');
    expect(el).toBeTruthy();
    fireEvent.press(el);
    expect(screen.getByText('No GPS')).toBeTruthy();
  });
});

/**
 * Tests for LiveGuidanceOverlay component.
 * Uses React.createElement directly to avoid Vitest's TSX transform issue
 * with Vite 7 (oxc can't parse TypeScript `import type`).
 */

import { describe, expect, it, vi } from 'vitest';
import * as React from 'react';
import { render, screen } from '@testing-library/react-native';
import { LiveGuidanceOverlay } from './LiveGuidanceOverlay';
import { ConfidenceLevel, GuidancePhase, GuidanceState } from '../../routing/guidanceState';

const h = React.createElement;

// ─── Minimal fixture builders ──────────────────────────────────────────────

function makeNode(id: string, label: string) {
  return {
    id,
    label,
    x: 0.5,
    y: 0.5,
    type: 'room' as const,
    searchable: true,
    floorId: 1,
  };
}

function makeStep(instruction: string, distanceM = 10) {
  return {
    instruction,
    icon: 'straight' as const,
    distanceM,
    durationSec: 10,
    isAccessibleSegment: false,
    floorId: 1,
    floorNumber: 1,
  };
}

function makeRoute(overrides?: { destinationLabel?: string; steps?: { instruction: string; icon: string; distanceM: number; durationSec: number; isAccessibleSegment: boolean; floorId: number; floorNumber: number }[] }) {
  const dest = makeNode('dest', overrides?.destinationLabel ?? 'Engineering Lab');
  const steps = overrides?.steps ?? [
    makeStep('Walk straight to the elevators', 8),
    makeStep('Turn left at the lobby', 5),
  ];
  return {
    phase: 'ready' as const,
    start: makeNode('start', 'Library Entrance'),
    destination: dest,
    routeMode: 'standard' as const,
    path: {
      found: true,
      nodeIds: ['start', 'n1', 'n2', 'dest'],
      totalDistance: 0.1,
      segments: [],
    },
    directions: {
      steps,
      totalDistanceNorm: steps.reduce((s, st) => s + st.distanceM, 0),
      totalDurationSec: steps.reduce((s, st) => s + st.durationSec, 0),
    },
    errorMessage: null,
  };
}

function makeState(
  phase: GuidancePhase,
  overrides?: { positionConfidence?: ConfidenceLevel; currentStepIndex?: number },
): GuidanceState {
  const route = makeRoute() as GuidanceState['route'];
  return {
    phase,
    route,
    currentStepIndex: overrides?.currentStepIndex ?? 0,
    snappedPosition: { x: 0.5, y: 0.5 },
    snappedNodeId: 'start',
    heading: 90,
    headingConfidence: 10,
    positionConfidence: overrides?.positionConfidence ?? 'high',
    lastFixTimestamp: Date.now(),
    offRouteDetectedAt: null,
    offRouteFixCount: 0,
    rerouteResult: null,
    currentFloorId: 1,
  };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('LiveGuidanceOverlay — phase rendering', () => {
  const onConfirmPosition = vi.fn();
  const onStopGuidance = vi.fn();

  it('renders null for idle phase', () => {
    const state = makeState('idle');
    const { toJSON } = render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(toJSON()).toBeNull();
  });

  it('renders low-confidence banner with confirm button', () => {
    const state = makeState('low-confidence', { positionConfidence: 'low' });
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('low-confidence-banner')).toBeTruthy();
    expect(screen.getByTestId('confirm-position-btn')).toBeTruthy();
    expect(screen.getByText(/Can't confirm your location/)).toBeTruthy();
  });

  it('renders guidance card for guiding phase', () => {
    const state = makeState('guiding', { positionConfidence: 'high', currentStepIndex: 0 });
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('guiding-card')).toBeTruthy();
  });

  it('guiding card shows step instruction text', () => {
    const state = makeState('guiding', { currentStepIndex: 0 });
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByText('Walk straight to the elevators')).toBeTruthy();
  });

  it('guiding card shows progress indicator', () => {
    const state = makeState('guiding', { currentStepIndex: 0 });
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    // 2 steps total, currently on step 1
    expect(screen.getByText('Step 1 of 2')).toBeTruthy();
  });

  it('guiding card shows stop guidance button', () => {
    const state = makeState('guiding', { currentStepIndex: 0 });
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('stop-guidance-btn')).toBeTruthy();
    expect(screen.getByText('End guidance')).toBeTruthy();
  });

  it('renders rerouting banner with spinner text', () => {
    const state = makeState('rerouting');
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('rerouting-banner')).toBeTruthy();
    expect(screen.getByText('Recalculating your route...')).toBeTruthy();
  });

  it('renders arrived card with destination name', () => {
    const state = makeState('arrived');
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('arrived-card')).toBeTruthy();
    expect(screen.getByText("You've arrived!")).toBeTruthy();
    expect(screen.getByText('Engineering Lab')).toBeTruthy();
  });

  it('arrived card shows done button', () => {
    const state = makeState('arrived');
    render(
      h(LiveGuidanceOverlay, { guidanceState: state, onConfirmPosition, onStopGuidance }),
    );
    expect(screen.getByTestId('done-btn')).toBeTruthy();
    expect(screen.getByText('Done')).toBeTruthy();
  });
});

